REVOKE ALL ON public.currencies, public.exchange_rates FROM anon, authenticated;
--> statement-breakpoint
-- A currency is written once and never changed or removed, so the base currency stays the base
-- currency. A rate can be corrected; who first entered it, and for which currency and day, cannot.
GRANT SELECT, INSERT ON public.currencies, public.exchange_rates TO app_runtime;
--> statement-breakpoint
GRANT UPDATE (rate, source, updated_at, updated_by) ON public.exchange_rates TO app_runtime;
--> statement-breakpoint

