--> statement-breakpoint
ALTER TABLE public.exchange_rates FORCE ROW LEVEL SECURITY;
--> statement-breakpoint

-- Every member reads their company's currencies and rates: documents in a foreign currency need
-- them. An owner or an accountant adds currencies and rates; only an owner sets the base currency.
CREATE POLICY currencies_select ON public.currencies FOR SELECT TO app_runtime
  USING (tenant_id = (SELECT app.tenant_id()));
--> statement-breakpoint
CREATE POLICY currencies_insert ON public.currencies FOR INSERT TO app_runtime
  WITH CHECK (
    tenant_id = (SELECT app.tenant_id())
    AND created_by = (SELECT app.current_user_id())
    AND CASE WHEN is_base
          THEN (SELECT app.tenant_role()) = 'owner'
          ELSE (SELECT app.tenant_role()) IN ('owner', 'accountant')
        END
  );
--> statement-breakpoint

CREATE POLICY exchange_rates_select ON public.exchange_rates FOR SELECT TO app_runtime
  USING (tenant_id = (SELECT app.tenant_id()));
--> statement-breakpoint
CREATE POLICY exchange_rates_insert ON public.exchange_rates FOR INSERT TO app_runtime
  WITH CHECK (
    tenant_id = (SELECT app.tenant_id())
    AND (SELECT app.tenant_role()) IN ('owner', 'accountant')
    AND created_by = (SELECT app.current_user_id())
    AND updated_by = (SELECT app.current_user_id())
  );
--> statement-breakpoint
CREATE POLICY exchange_rates_update ON public.exchange_rates FOR UPDATE TO app_runtime
  USING (tenant_id = (SELECT app.tenant_id()) AND (SELECT app.tenant_role()) IN ('owner', 'accountant'))
  WITH CHECK (
    tenant_id = (SELECT app.tenant_id())
    AND (SELECT app.tenant_role()) IN ('owner', 'accountant')
    AND updated_by = (SELECT app.current_user_id())
  );
--> statement-breakpoint

-- ── hand-written: the base currency has no rate ─────────────────────────────────────────────────
-- One unit of the base currency is always one unit of the base currency. A rate row for it would
-- be read by nothing and could only mislead, so the database refuses it whoever writes it.
CREATE FUNCTION app.refuse_base_currency_rate() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.currencies c
    WHERE c.tenant_id = NEW.tenant_id AND c.id = NEW.currency_id AND c.is_base
  ) THEN
    RAISE EXCEPTION 'the base currency has no exchange rate' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.refuse_base_currency_rate() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER exchange_rates_refuse_base
  BEFORE INSERT ON public.exchange_rates
  FOR EACH ROW EXECUTE FUNCTION app.refuse_base_currency_rate();
